```tsx
const EventCTAs = ({ event, className }) => {
  // Track analytics for CTA clicks
  const trackTicketClick = () => {
    // Analytics tracking code
    console.log('Ticket CTA clicked', event.id);
  };

  const trackDirectionsClick = (provider) => {
    // Analytics tracking code
    console.log(`Directions CTA clicked: ${provider}`, event.id);
  };

  // Generate directions URLs
  const getGoogleMapsUrl = () => {
    const address = encodeURIComponent(`${event.venue}, ${event.address}, ${event.city}, ${event.state}`);
    return `https://www.google.com/maps/search/?api=1&query=${address}`;
  };

  const getAppleMapsUrl = () => {
    const address = encodeURIComponent(`${event.venue}, ${event.address}, ${event.city}, ${event.state}`);
    return `https://maps.apple.com/?q=${address}`;
  };

  const isIOS = typeof navigator !== 'undefined' && /iPad|iPhone|iPod/.test(navigator.userAgent);
  const directionsUrl = isIOS ? getAppleMapsUrl() : getGoogleMapsUrl();

  return (
    <div className={`flex flex-col space-y-3 ${className}`}>
      {event.ticketUrl && (
        <a
          href={event.ticketUrl}
          target="_blank"
          rel="noopener noreferrer"
          onClick={trackTicketClick}
          className="bg-blue-600 text-white py-3 px-6 rounded-lg font-medium text-center hover:bg-blue-700 transition-colors"
          aria-label="Buy tickets for this event"
        >
          {event.isFree ? 'Register - Free' : event.isSoldOut ? 'Sold Out' : `Buy Tickets - $${event.price}`}
        </a>
      )}

      <a
        href={directionsUrl}
        target="_blank"
        rel="noopener noreferrer"
        onClick={() => trackDirectionsClick(isIOS ? 'apple' : 'google')}
        className="bg-gray-100 text-gray-800 py-3 px-6 rounded-lg font-medium text-center hover:bg-gray-200 transition-colors"
        aria-label="Get directions to this event"
      >
        Get Directions
      </a>
    </div>
  );
};
